    "stat5" TEXT,
    "set5" TEXT,
    "val5" TEXT,
    "func6" TEXT,
    "stat6" TEXT,
    "set6" TEXT,
    "val6" TEXT,
    "func7" TEXT,
    "stat7" TEXT,
